import os
import unittest

from check_pr_body import check

ROOT = os.path.join(os.path.dirname(__file__), "..", "..", "..")
with open(os.path.join(ROOT, ".github", "pull_request_template.md"), encoding="utf-8") as source:
    TEMPLATE = source.read()

GOOD = """## Summary
- Validate descriptions so reviewers see consistent context.
No diagram: documentation-only change.

## Types of Changes
- [x] Domestic

## Test Plan:
- Run unit tests: all pass.

## Jira Issues:
n/a
"""


class CheckPrBody(unittest.TestCase):
    def assert_rule(self, body, rule):
        self.assertTrue(any(rule in error for error in check(TEMPLATE, body)))

    def test_filled_template_passes(self):
        self.assertEqual(check(TEMPLATE, GOOD), [])

    def test_missing_section_fails(self):
        self.assert_rule(GOOD.replace("## Jira Issues:", "## Issues"), "missing template sections")

    def test_reordered_sections_fail(self):
        body = GOOD.replace("## Summary", "## TEMP").replace("## Test Plan:", "## Summary").replace("## TEMP", "## Test Plan:")
        self.assert_rule(body, "out of order")

    def test_empty_section_fails_after_comments_stripped(self):
        self.assert_rule(GOOD.replace("n/a", "<!-- notes -->"), 'section "Jira Issues:" is empty')

    def test_unfilled_template_fails(self):
        self.assert_rule(TEMPLATE, 'section "Summary" is empty')

    def test_headings_inside_fences_are_ignored(self):
        for fence in ("```", "~~~~"):
            with self.subTest(fence=fence):
                body = GOOD.replace("n/a", f"n/a\n{fence}text\n## Summary\n{fence}\n")
                self.assertEqual(check(TEMPLATE, body), [])

    def test_no_ticked_type_fails(self):
        self.assert_rule(GOOD.replace("[x]", "[ ]"), "checkbox")

    def test_uppercase_tick_passes(self):
        self.assertEqual(check(TEMPLATE, GOOD.replace("[x]", "[X]")), [])

    def test_tick_outside_types_does_not_count(self):
        self.assert_rule(GOOD.replace("[x]", "[ ]") + "\n- [x] extra\n", "checkbox")

    def test_tick_in_code_does_not_count(self):
        self.assert_rule(GOOD.replace("- [x] Domestic", "```text\n- [x] Domestic\n```"), "checkbox")

    def test_long_dashes_fail(self):
        for dash in ("\u2013", "\u2014", "\u2015"):
            with self.subTest(dash=ascii(dash)):
                self.assert_rule(GOOD + dash, "dash")

    def test_attribution_fails(self):
        for text in ("\U0001F916", "Co-Authored-By: someone", "Generated with Claude Code", "generated by [Codex]", "generated by Copilot", "generated with ChatGPT", "generated by Gemini", "generated with Cursor", "generated by an AI"):
            with self.subTest(text=text):
                self.assert_rule(GOOD + text, "attribution")

    def test_ordinary_generation_is_allowed(self):
        self.assertEqual(check(TEMPLATE, GOOD + "Generated with a documentation formatter.",), [])

    def test_internal_references_fail(self):
        references = (".ag" + "ent/", "~/" + ".claude", "~/" + ".backlog", "/tmp/" + "claude", "tk" + "t#" + "123", "tk" + "t-" + "123")
        for text in references:
            with self.subTest(text=text):
                self.assert_rule(GOOD + text, "internal-only")

    def test_missing_diagram_choice_fails(self):
        self.assert_rule(GOOD.replace("No diagram: documentation-only change.", ""), "Mermaid")

    def test_mermaid_passes(self):
        body = GOOD.replace("No diagram: documentation-only change.", "```mermaid\nflowchart LR\nA --> B\n```")
        self.assertEqual(check(TEMPLATE, body), [])

    def test_other_code_is_not_a_diagram(self):
        self.assert_rule(GOOD.replace("No diagram: documentation-only change.", "```text\nexample\n```"), "Mermaid")

    def test_long_prose_fails(self):
        self.assert_rule(GOOD + "word " * 301, "prose words")

    def test_nonprose_does_not_count(self):
        additions = (
            "\n```text\n" + "word\n" * 400 + "```\n",
            "\n| Column | Value |\n| --- | --- |\n" + "| word | word |\n" * 400,
            "\n" + "- [ ] word\n" * 400,
            "\n<!-- " + "word " * 400 + " -->\n",
        )
        for addition in additions:
            with self.subTest(addition=addition[:30]):
                self.assertEqual(check(TEMPLATE, GOOD + addition), [])


if __name__ == "__main__":
    unittest.main()
